WITH base AS (SELECT id, name, email, country, city, segment, signup_date, is_active, age, SUBSTRING(segment, 1, 2) AS segment_prefix, CONCAT(country, '/', segment) AS country_segment FROM customers WHERE signup_date >= DATE '2023-03-22' AND segment IS NOT NULL AND name IS NOT NULL) SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM orders ch WHERE ch.customer_id = s.id AND ch.discount BETWEEN 0.15 AND 0.31);
